object NewBalanceChapter2Part5 {
    val quests = listOf(
        Quest("CH2-173",2,173,"Dark Rituals",category="Orc City - Ur Hash-Nar",giver = "Ur Hash-Nar",location="Orc City - Ur Hash-Nar",prerequisites="Complete Orc Shrines and gain access to the Brotherhood swamp camp.",summary="Help Ur-Hash-Nar stop an undead ritual at the Brotherhood's old swamp camp and defeat the summoned archdemon.",walkthroughSteps=listOf("Complete Orc Shrines and ask shaman Ur-Hash-Nar about dark rituals.","Travel to the old Brotherhood swamp camp in the Valley of Mines and speak with Tor Dal and his two orc companions.","Learn that a powerful demon is inside the old temple; report this to Ur-Hash-Nar and choose whether to ask Ur-Thrall for reinforcements.","Prepare high poison resistance before entering the swamp, then defeat the undead and named bosses in the old temple.","Defeat necromancer Aktameron and recover the summoning book; read it at the pentagram to summon the archdemon Mor'Bar.","Kill Mor'Bar, loot the necessary evidence, report to Tor Dal and return to Ur-Hash-Nar."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Do not kill the quest archdemon before activating Dark Rituals. The Brotherhood swamp is poisonous; prepare protection. Source: https://rpgrussia.com/threads/temnye-ritualy.66974/",searchTags=listOf("dark rituals","orc city - ur hash-nar","local quest giver in orc city - ur hash-nar")),
        Quest("CH2-174",2,174,"Hunting Muritan",category="Orc City - Ur-Karras",giver = "Ur-Karras",location="Orc City - Ur-Karras",prerequisites="Complete An Unexpected Meeting and save Ur-Karras in Chapter 1.",summary="Kill a Muritan and bring its poisonous fang to Ur-Karras in Orc City.",walkthroughSteps=listOf("Meet Ur-Karras again in Orc City after rescuing him in Khorinis.","Ask about the hunting assignment he previously failed.","He wants a poisonous Muritan fang.","Hunt a Muritan: one spawns in the deep cave below the eastern gate of Khorinis when you accept; others live on the coast, in the West Coast swamp or north-west of Garond's castle.","Learn to remove the fang if necessary, then collect it.","Return the fang to Ur-Karras for experience and Orc City reputation."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Complete the required orc and regional quests before returning to the quest giver. Source: https://rpgrussia.com/threads/oxota-na-muritana.66977/",searchTags=listOf("hunting muritan","orc city - ur-karras","local quest giver in orc city - ur-karras")),
        Quest("CH2-175",2,175,"Message from Ur-Karras",category="Orc City - Ur-Karras",giver = "Ur-Karras",location="Orc City - Ur-Karras",prerequisites="Complete Muritan Hunt and maintain Ur-Karras's trust.",summary="Deliver Ur-Karras's message to orc leader Nag Shor—or betray him by taking it to Garond.",walkthroughSteps=listOf("Complete Muritan Hunt and ask Ur-Karras about his next request.","Carry Ur-Karras's letter to Nag Shor, chieftain of the High Rock orcs above the ice dragon's cavern; the Free Mine mountain pass also leads to the area.","Deliver it to Nag Shor and report to Ur-Karras for the loyal resolution.","Alternatively show the letter to Garond at the castle to betray Ur-Karras.","If choosing betrayal, watch for the black orc courier by Orc City's entrance; killing and looting him can begin Strange Key.","Be aware that Ur-Karras will stop cooperating if he learns you betrayed him."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Loyal delivery and betrayal are mutually exclusive outcomes; the betrayal route may close Ur-Karras's subsequent questline. Source: https://rpgrussia.com/threads/poslanie-ur-karrasa.66978/",searchTags=listOf("message from ur-karras","orc city - ur-karras","local quest giver in orc city - ur-karras")),
