        Quest("CH2-177",2,177,"Paladin Provisions",category="Orc City - Ur-Karras",giver = "Ur-Karras",location="Orc City - Ur-Karras",prerequisites="Complete Message from Ur-Karras through a route that preserves Ur-Karras's trust.",summary="Sabotage the paladins' food crates inside Garond's castle at Ur-Karras's request.",walkthroughSteps=listOf("After completing Message from Ur-Karras, ask him how else you can help the orcs.","Agree to sabotage the paladin provisions and travel to Garond's castle.","Obtain the supply storeroom key from the small tower over Engor's hall.","Enter the storeroom and use a lit torch to ignite the target supply boxes.","Return to Ur-Karras and report the sabotage."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="You can refuse the sabotage for an Innos-favor outcome, but Ur-Karras may refuse subsequent quests including A Difficult Choice. Source: https://rpgrussia.com/threads/prodovolstvie-paladinov.66980/",searchTags=listOf("paladin provisions","orc city - ur-karras","local quest giver in orc city - ur-karras")),
